-- Discount limits (D-14): cashier 10 %, manager 20 %; above that needs step-up approval.
INSERT INTO cl.role_discount_limits (role_id, max_percent)
SELECT id, CASE key WHEN 'cashier' THEN 10 WHEN 'manager' THEN 20 END
  FROM cl.roles WHERE key IN ('cashier','manager');
